document.addEventListener('click',e=>{const pageBtn=e.target.closest('[data-page]');if(pageBtn){activePage=pageBtn.dataset.page;selectedPet=null;render();return}const pub=e.target.closest('[data-public-page]');if(pub){publicPage=pub.dataset.publicPage;render();return}const open=e.target.closest('[data-open-pet]');if(open){selectedPet=open.dataset.openPet;activePage='patient-profile';render();return}const panelBtn=e.target.closest('[data-panel]');if(panelBtn){setPanel(panelBtn.dataset.panel);return}const actionBtn=e.target.closest('[data-action]');if(actionBtn){const a=actionBtn.dataset.action;if(a==='close-modal')$('#modal').close();else if(a==='reset'){if(confirm('Zastąpić lokalny zestaw fikcyjnymi danymi demonstracyjnymi?')){try{localStorage.setItem(STORAGE_KEY,JSON.stringify(createSeed()));state=createSeed();corruptStorage=false;render();notify('Dane demonstracyjne przywrócono.')}catch{notify('Nie udało się zapisać w pamięci przeglądarki.')}}}else if(a==='export')exportData();else if(a==='toggle-public-pages'){window.showPublicNav=!window.showPublicNav;render()}else if(a==='next-public'){publicPage=({home:'about',about:'clinics',clinics:'owners',owners:'how',how:'pilot',pilot:'faq',faq:'home'})[publicPage];render()}else if(a==='go-clinic')setPanel('clinic');else if(a==='go-owner')setPanel('owner');else if(a==='open-owner-pet'){activePage='owner-history';render()}else actionModal(a);return}});
$('#panel-switch').addEventListener('change',e=>setPanel(e.target.value));$('#account-switch').addEventListener('change',e=>{if(panel==='owner')ownerId=e.target.value;render()});$('#export-button').addEventListener('click',exportData);
function exportData(){const blob=new Blob([JSON.stringify(state,null,2)],{type:'application/json'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download='petid-demo-data.json';a.click();URL.revokeObjectURL(url);notify('Pobrano lokalny eksport danych demo.')}
function init(){state=loadState();$('#panel-switch').innerHTML='<option value="public">Strona publiczna</option><option value="clinic">Panel kliniki</option><option value="owner">Panel opiekuna</option><option value="admin">Panel administratora</option>';$('#account-switch').innerHTML=state.users.map(u=>`<option value="${esc(u.id)}">${esc(u.name)} · ${esc(roleNames[u.role])}</option>`).join('');$('#account-switch').value=state.users[0].id;$('#panel-switch').value=panel;render()}
init();
